def topo(nodes, edges):
    # Build adjacency list and in-degree map
    # edges: (prerequisite, dependent) means prerequisite -> dependent
    # We need to find lexicographically smallest topological order

    # Collect all nodes
    node_set = set(nodes)

    # Build adjacency list: for each node, list of nodes it points to
    adj = {node: [] for node in node_set}
    in_degree = {node: 0 for node in node_set}

    # Process edges, ignoring duplicates
    seen_edges = set()
    for u, v in edges:
        if (u, v) in seen_edges:
            continue
        seen_edges.add((u, v))
        adj[u].append(v)
        in_degree[v] += 1

    # Use a min-heap (priority queue) to always pick the lexicographically smallest node with in-degree 0
    import heapq

    heap = []
    for node in node_set:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(node_set):
        raise ValueError("Cycle detected")

    return result
